IF SCHEMA_ID(N'nucleo') IS NULL EXEC(N'CREATE SCHEMA nucleo');
IF SCHEMA_ID(N'identidad') IS NULL EXEC(N'CREATE SCHEMA identidad');
IF SCHEMA_ID(N'organizaciones') IS NULL EXEC(N'CREATE SCHEMA organizaciones');
IF SCHEMA_ID(N'legal') IS NULL EXEC(N'CREATE SCHEMA legal');
IF SCHEMA_ID(N'territorio') IS NULL EXEC(N'CREATE SCHEMA territorio');
CREATE TABLE nucleo.VersionesEsquema (Version nvarchar(80) NOT NULL PRIMARY KEY, FechaAplicacion datetime2(0) NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE nucleo.EventosInicializacion (CodigoEvento nvarchar(80) NOT NULL PRIMARY KEY, FechaFinalizacion datetime2(0) NOT NULL);
CREATE TABLE identidad.Personas (Id uniqueidentifier NOT NULL PRIMARY KEY, PrimerNombre nvarchar(120) NOT NULL, SegundoNombre nvarchar(120) NULL, PrimerApellido nvarchar(120) NOT NULL, SegundoApellido nvarchar(120) NULL, CodigoTipoIdentificacion nvarchar(10) NOT NULL, NumeroIdentificacionNormalizado nvarchar(120) NOT NULL, CorreoNormalizado nvarchar(320) NOT NULL, Telefono nvarchar(40) NULL, HashContrasena nvarchar(512) NOT NULL, EstadoCuenta nvarchar(30) NOT NULL, EstadoVerificacionCorreo nvarchar(30) NOT NULL, FechaCreacion datetime2(0) NOT NULL, FechaActualizacion datetime2(0) NOT NULL, CONSTRAINT UQ_Personas_Correo UNIQUE (CorreoNormalizado), CONSTRAINT UQ_Personas_Identificacion UNIQUE (CodigoTipoIdentificacion,NumeroIdentificacionNormalizado), CONSTRAINT CK_Personas_EstadoCuenta CHECK (EstadoCuenta IN (N'activa',N'suspendida',N'cerrada')), CONSTRAINT CK_Personas_EstadoCorreo CHECK (EstadoVerificacionCorreo IN (N'no_configurada',N'pendiente',N'verificada')));
CREATE TABLE identidad.Roles (Codigo nvarchar(40) NOT NULL PRIMARY KEY, Nombre nvarchar(120) NOT NULL);
INSERT INTO identidad.Roles (Codigo,Nombre) VALUES (N'administrador_sistema',N'Administradora o administrador del sistema'),(N'externo',N'Persona externa');
CREATE TABLE identidad.PersonasRoles (IdPersona uniqueidentifier NOT NULL, CodigoRol nvarchar(40) NOT NULL, FechaAsignacion datetime2(0) NOT NULL, PRIMARY KEY(IdPersona,CodigoRol), CONSTRAINT FK_PersonasRoles_Persona FOREIGN KEY(IdPersona) REFERENCES identidad.Personas(Id), CONSTRAINT FK_PersonasRoles_Rol FOREIGN KEY(CodigoRol) REFERENCES identidad.Roles(Codigo));
CREATE TABLE territorio.Departamentos (Codigo nvarchar(10) NOT NULL PRIMARY KEY, Nombre nvarchar(160) NOT NULL);
CREATE TABLE territorio.Municipios (Codigo nvarchar(10) NOT NULL, CodigoDepartamento nvarchar(10) NOT NULL, Nombre nvarchar(160) NOT NULL, PRIMARY KEY(Codigo,CodigoDepartamento), CONSTRAINT FK_Municipios_Departamento FOREIGN KEY(CodigoDepartamento) REFERENCES territorio.Departamentos(Codigo));
CREATE TABLE organizaciones.Organizaciones (Id uniqueidentifier NOT NULL PRIMARY KEY, Nombre nvarchar(240) NOT NULL, NumeroIdentificacion nvarchar(80) NULL, CorreoContacto nvarchar(320) NULL, CodigoDepartamento nvarchar(10) NOT NULL, CodigoMunicipio nvarchar(10) NOT NULL, Estado nvarchar(30) NOT NULL, FechaCreacion datetime2(0) NOT NULL, FechaActualizacion datetime2(0) NOT NULL, CONSTRAINT FK_Organizaciones_Departamento FOREIGN KEY(CodigoDepartamento) REFERENCES territorio.Departamentos(Codigo), CONSTRAINT FK_Organizaciones_Municipio FOREIGN KEY(CodigoMunicipio,CodigoDepartamento) REFERENCES territorio.Municipios(Codigo,CodigoDepartamento), CONSTRAINT CK_Organizaciones_Estado CHECK (Estado IN (N'activa',N'archivada')));
CREATE TABLE organizaciones.Administradores (IdOrganizacion uniqueidentifier NOT NULL, IdPersona uniqueidentifier NOT NULL, FechaAsignacion datetime2(0) NOT NULL, FechaRetiro datetime2(0) NULL, PRIMARY KEY(IdOrganizacion,IdPersona), CONSTRAINT FK_Administradores_Organizacion FOREIGN KEY(IdOrganizacion) REFERENCES organizaciones.Organizaciones(Id), CONSTRAINT FK_Administradores_Persona FOREIGN KEY(IdPersona) REFERENCES identidad.Personas(Id));
CREATE TABLE legal.Documentos (Id uniqueidentifier NOT NULL PRIMARY KEY, Codigo nvarchar(80) NOT NULL, Version nvarchar(40) NOT NULL, Titulo nvarchar(240) NOT NULL, UrlPublica nvarchar(500) NOT NULL, EsVigente bit NOT NULL, FechaPublicacion datetime2(0) NOT NULL, CONSTRAINT UQ_Documentos_CodigoVersion UNIQUE(Codigo,Version));
CREATE UNIQUE INDEX UX_Documentos_Vigente ON legal.Documentos(Codigo) WHERE EsVigente=1;
CREATE TABLE legal.Aceptaciones (Id uniqueidentifier NOT NULL PRIMARY KEY, IdPersona uniqueidentifier NOT NULL, IdDocumento uniqueidentifier NOT NULL, FechaAceptacion datetime2(0) NOT NULL, CONSTRAINT UQ_Aceptaciones_PersonaDocumento UNIQUE(IdPersona,IdDocumento), CONSTRAINT FK_Aceptaciones_Persona FOREIGN KEY(IdPersona) REFERENCES identidad.Personas(Id), CONSTRAINT FK_Aceptaciones_Documento FOREIGN KEY(IdDocumento) REFERENCES legal.Documentos(Id));
CREATE TABLE identidad.Sesiones (Id uniqueidentifier NOT NULL PRIMARY KEY, IdPersona uniqueidentifier NOT NULL, HashSecreto varbinary(64) NOT NULL, FechaInicio datetime2(0) NOT NULL, FechaUltimaActividad datetime2(0) NOT NULL, FechaVencimientoInactividad datetime2(0) NOT NULL, FechaVencimientoMaximo datetime2(0) NOT NULL, FechaRevocacion datetime2(0) NULL, CONSTRAINT UQ_Sesiones_HashSecreto UNIQUE(HashSecreto), CONSTRAINT FK_Sesiones_Persona FOREIGN KEY(IdPersona) REFERENCES identidad.Personas(Id));
CREATE INDEX IX_Sesiones_Persona ON identidad.Sesiones(IdPersona,FechaRevocacion,FechaVencimientoMaximo);
INSERT INTO nucleo.VersionesEsquema (Version) VALUES (N'001_identidad');
